arguments.command:
curl -s -X POST https://api.linear.app/graphql -H 'Content-Type: application/json' -H 'Authorization: <TOKEN>' -d '{"query":"query { t: __type(name: \"Mutation\") { fields { name args { name type { name kind ofType { name kind } } } } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
for f in d['data']['t']['fields']:
    if 'oc' in f['name'].lower() or 'roject' in f['name'].lower() or 'ocument' in f['name'].lower():
        args={a['name']:(a['type'].get('name') or (a['type'].get('ofType') or {}).get('name') or a['type'].get('kind')) for a in f['args']}
        print(f['name'], args)
"

